// Generated from /Users/nikita/Desktop/semantic core promo music.xlsx

export interface SeoAlias {
  title: string;
  desc: string;
  h1: string;
  keywords: string;
  body: string;
  faq: { q: string; a: string }[];
  type?: string;
}

const D = 'https://promo-music.ru';

// ───────────────────────────────────────────────────────
// Helper: render related links list
function rel(items: Array<[string, string]>): string {
  return items.map(([href, text]) => `<li><a href="${D}${href}">${text}</a></li>`).join('');
}

