<p>Когда артист говорит «хочу в чарт», он чаще всего имеет в виду три разные вещи. Региональный или жанровый чарт, куда зайти проще всего. Чарт новинок, где трек конкурирует только со свежими релизами. И большой Топ-100 площадки, где рядом стоят имена с миллионными аудиториями. Стратегия под каждый из них отличается, и путать их, значит сливать бюджет.</p>
