<p>После релиза площадки включают алгоритмический буст: трек попадает в автоплейлисты, «Премьеры», радио по похожим артистам. Этот буст живёт примерно две недели. Если вы соберёте плотный поток прослушиваний в эти 14 дней, алгоритм решит, что трек «нравится людям», и сам начнёт его раздавать. Пропустили окно, и дальше придётся толкать трек руками против инерции системы.</p>
