function buildGenrePage(g: GenreData): SeoAlias {
  const title = `${g.ru}: артисты, треки, история жанра | ПРОМО.МУЗЫКА`;
  const desc = `${g.ru} (${g.en || g.slug}) на ПРОМО.МУЗЫКА. История жанра, ключевые исполнители, темп ${g.bpm}, плейлисты и новые релизы. ${g.vibe.split('.')[0]}.`;
  const h1 = `${g.ru}: история, артисты, плейлисты`;
  const artistList = g.artists.map(a => `<li>${a}</li>`).join('');
  return {
    title, desc, h1,
    keywords: g.keywords,
    body: `<article class="genre">
<h1>${h1}</h1>
<p class="lead">${g.long}</p>

<section>
<h2>История жанра</h2>
<p>${g.origin}</p>
</section>

<section>
<h2>Ключевые артисты</h2>
<ul class="artists">${artistList}</ul>
</section>

<section>
<h2>Атмосфера и настроение</h2>
<p>${g.vibe}</p>
</section>

<section>
<h2>Технические параметры</h2>
<p>Темп: <strong>${g.bpm}</strong>. Этот диапазон не догма, исключения встречаются часто. Но если вы готовите DJ-сет в этом жанре, ориентируйтесь на эти границы.</p>
</section>

<section><h2>Связанные разделы</h2><ul>${rel([
  ['/charts', 'Главный чарт ПРОМО.МУЗЫКА'],
  ['/new', 'Свежие новинки музыки'],
  ['/radio/listen', 'Радио по жанрам'],
  ['/promo', 'Промо музыки в этом жанре'],
])}</ul></section>
</article>`,
    faq: g.faq,
  };
}

