function buildBlogPage(b: BlogData): SeoAlias {
  const sectionsHtml = b.sections.map(s => `<section><h2>${s.h2}</h2><p>${s.body}</p></section>`).join('\n');
  return {
    title: b.title,
    desc: b.desc,
    h1: b.h1,
    keywords: b.keywords,
    body: `<article class="blog-post">
<h1>${b.h1}</h1>
<p class="lead">${b.intro}</p>

${sectionsHtml}

<section><h2>Связанные материалы</h2><ul>${rel(b.related)}</ul></section>
</article>`,
    faq: b.faq,
    type: 'article',
  };
}

export const BLOG_PAGES: Record<string, SeoAlias> = Object.fromEntries(
  BLOG.map(b => [`/blog/${b.slug}`, buildBlogPage(b)])
);

